"""cc_z2gen.py -- order of the group generated by G_l and the involution t for each PSL Z2-partial class
(tests the report's statement that TM1/TM2 come from S4 subgroups and the Z7 class needs PSL's Z2)."""
import numpy as np, itertools, json
base = "/home/user/gifgaf0.github.io/seed/experiments/E4_family_symmetry/crosscheck/out/"
PSL = list(np.load(base + "PSL_elements.npy"))
I = np.eye(3, dtype=complex)
key = lambda M: tuple(np.round(M, 6).ravel().view(float))
def order(g):
    P = I.copy()
    for n in range(1, 30):
        P = P @ g
        if np.allclose(P, I): return n
def gen_order(gens):
    els = {key(I): I}; fr = [I]
    while fr:
        new = []
        for M in fr:
            for g in gens:
                N = g @ M
                if key(N) not in els: els[key(N)] = N; new.append(N)
        fr = new
    return len(els)
invol = [g for g in PSL if order(g) == 2]
out = {}
for o in (3, 4, 7):
    g = next(x for x in PSL if order(x) == o)
    w, V = np.linalg.eig(g); V = V / np.linalg.norm(V, axis=0)
    res = {}
    for t in invol:
        vals, W = np.linalg.eigh((t + t.conj().T) / 2)
        vp = W[:, np.argmax(vals)]
        col = tuple(np.sort(np.round(np.abs(V.conj().T @ vp) ** 2, 4)))
        res.setdefault(col, set()).add(gen_order([g, t]))
    out[f"Z{o}"] = {str(k): sorted(v) for k, v in res.items()}
    for k, v in res.items(): print(f"G_l=Z{o} fixed column {k}: |<G_l, t>| = {sorted(v)}")
json.dump(out, open(base + "z2gen_cc.json", "w"), indent=1)
